export const GOJO_SKILLS={blue:{cooldown:7,cast:.55,duration:1},red:{cooldown:9,cast:.65,duration:1.1},purple:{cooldown:16,cast:1.15,duration:1.6}};
export const gojo={name:'Gojo',assets:['gojo_v2','gojo_v2_vfx','gojo_v2_intro','gojo_v2_intro_vfx','gojo_v2_ultimate_vfx','gojo_v2_dialogue'],stats:{hp:1200,speed:205,melee:70,skillPower:100,cooldown:100,dodgeChance:20,blinkChance:15,blockChance:15,preferredRange:220},
 init(f){f.rage=0;f.rageLockUntil=0;f.rageReadyTick=null;f.personalUses=0;f.infinityReady=0;f.infinityChance=20;f.infinityUntil=0;f.gojoFields=[];for(const [k,v] of Object.entries({blue:1,red:2,purple:5})){f[k+'Cd']=v*f.cooldownFactor;f.skillUses[k]=0;}},
 onAct(f,state,d){if(!GOJO_SKILLS[state])return;f[state+'Cd']=GOJO_SKILLS[state].cooldown*f.cooldownFactor;f.skillUses[state]++;const t=d.pickTarget(f);f.gojoTarget=t?.uid;if(state==='blue'&&t){f.gojoFields.push({x:t.x,y:t.y,born:d.tick,expires:d.tick+72});}},
 tick(f,dt){for(const k of Object.keys(GOJO_SKILLS))f[k+'Cd']=Math.max(0,f[k+'Cd']-dt);},
 beforeStep(d){for(const f of d.fighters)if(f.id==='gojo')f.gojoFields=f.hp>0?f.gojoFields.filter(z=>d.tick<z.expires):[];},
 onDeath(d,f){f.gojoFields=[];f.infinityUntil=0;},
 incomingDamageMultiplier(d,f){if(d.tick>=f.infinityReady&&d.roll(f.infinityChance??20)){f.infinityReady=d.tick+240;f.infinityUntil=d.tick+24;d.event('infinityGuard',f,{x:f.x,y:f.y});return .3;}return 1;},
 updateAction(d,f,o,hits,dx,dy,distance,dt){const spec=GOJO_SKILLS[f.state];if(!spec)return false;const target=d.fighters.find(t=>t.uid===f.gojoTarget&&t.hp>0&&d.isEnemy(f,t))||o;
  if(f.age>=spec.cast&&!f.hit){f.hit=true;if(f.state==='blue'){const z=f.gojoFields.at(-1)||target;for(const t of d.fighters)if(t.hp>0&&d.isEnemy(f,t)&&Math.hypot(t.x-z.x,t.y-z.y)<140){hits.push({source:f,target:t,value:105,rootTicks:30});if(!d.isTransformProtected(t)&&!t.invulnerable){const tx=z.x-t.x,ty=z.y-t.y,n=Math.hypot(tx,ty)||1,move=Math.min(75,n);t.x+=tx/n*move;t.y+=ty/n*move;d.clampPosition(t);}}d.event('gojoBurst',f,{x:z.x,y:z.y,skill:'blue'});}
   else{const tx=target.x-f.x,ty=target.y-f.y,n=Math.hypot(tx,ty)||1,purple=f.state==='purple';f.face=Math.sign(tx)||f.face;d.shots.push({id:f.id,ownerUid:f.uid,kind:purple?'purple':'gojored',skill:f.state,damage:purple?290:165,radius:purple?38:25,piercing:purple,hitUids:[],knockback:purple?0:95,x:f.x+tx/n*45,y:f.y+ty/n*45,vx:tx/n*(purple?540:640),vy:ty/n*(purple?540:640),life:1.8,impactEvent:'gojoImpact'});d.event('fire',f,{skill:f.state});}}
  if(f.age>=spec.duration){f.state='idle';f.age=0;}return true;},
 chooseSkill(d,f,o,dx,dy,distance){for(const k of ['purple','blue','red'])if(f[k+'Cd']===0&&(k==='purple'?distance>140&&distance<650:k==='blue'?distance<460:distance<550)){d.act(f,k,dx,dy);return true;}return false;}
};
export function gojoPose(f,hurt=false){if(f.introAge!=null){const n=Math.min(11,Math.floor(f.introAge/2.5*12));return {row:Math.floor(n/6),frame:n%6};}const s=hurt?'hurt':f.state,spec=GOJO_SKILLS[s],row=({idle:0,run:1,melee:f.combo%2?2:3,dash:4,guard:5,hurt:6,defeat:7,blue:8,red:9,purple:10})[s]??0;return {row,frame:spec?Math.min(5,Math.floor(f.age/spec.duration*6)):['melee','dash','hurt','defeat'].includes(s)?Math.min(5,Math.floor(f.age*(s==='dash'?24:10))):Math.floor(f.age*9)%6};}
